{"python":"import re, math

def text(v):
    return '' if v is None else str(v).strip()

def parse_num(v):
    s = text(v)
    if not s:
        return None
    is_pct = '%' in s
    m = re.search(r'-?\d+(?:\.\d+)?', s.replace(',', ''))
    if not m:
        return None
    x = float(m.group())
    if is_pct:
        return x / 100.0
    if x > 1.5:      # percentage stored without a percent sign
        return x / 100.0
    return x

def patient_id(v):
    s = text(v)
    m = re.search(r'(?:Patient[ -]?|P[- ]?|Organoid[ -]?|O[- ]?)(\d+)$', s, re.I)
    if m:
        n = int(m.group(1))
        return n if 1 <= n <= 128 else None
    m = re.fullmatch(r'(\d+)', s)
    return int(m.group(1)) if m else None

# Clinical truth from Supplementary Table 1: one row per patient, TRG/cCR column.
truth = {}
for sheet in ['page9', 'page10', 'page11']:
    for ri, row in enumerate(get_rows('supp.pdf', sheet)):
        pid = patient_id(row[0]) if row else None
        if pid is None:
            continue
        for cell in row:
            s = text(cell).upper().replace('PTRG', 'TRG')
            val = None
            if re.search(r'\bCCR\b', s):
                val = 1
            else:
                m = re.search(r'\bTRG\s*[=-]?\s*([0-3])\b', s)
                if not m:
                    m = re.fullmatch(r'([0-3])', s)
                if m:
                    val = 1 if int(m.group(1)) in (0, 1) else 0
            if val is not None:
                ref = f"supp.pdf/{sheet}/R{ri+1}C{row.index(cell)+1}"
                truth[pid] = {'value': val, 'ref': ref}
                break

# Locate the day-24 combined-chemoradiation size-ratio column in Supplementary Table 2.
score_sheets = ['page12','page13','page14','page15','page16','page17','page18']
score = {}
for sheet in score_sheets:
    rows = get_rows('supp.pdf', sheet)
    maxc = max((len(r) for r in rows), default=0)
    headers = []
    for c in range(maxc):
        h = ' '.join(text(r[c]) if c < len(r) else '' for r in rows[:5]).lower()
        headers.append(h)
    combo = [c for c,h in enumerate(headers) if ('combined' in h or 'chemoradiation' in h) and '24' in h]
    day24 = [c for c,h in enumerate(headers) if '24' in h]
    combonly = [c for c,h in enumerate(headers) if 'combined' in h or 'chemoradiation' in h]
    allowed = combo or day24 or combonly or list(range(maxc))
    for ri, row in enumerate(rows):
        pid = patient_id(row[0]) if row else None
        if pid is None or not (81 <= pid <= 128):
            continue
        candidates = []
        for ci, cell in enumerate(row):
            if ci not in allowed:
                continue
            h = headers[ci] if ci < len(headers) else ''
            if 'trg' in h or 'clinical' in h or 'outcome' in h:
                continue
            x = parse_num(cell)
            if x is not None and 0 <= x <= 1.5:
                candidates.append((ci, x))
        # Combined chemoradiation is the rightmost day-24 size-ratio column.
        if candidates:
            ci, x = max(candidates, key=lambda z: z[0])
            score[pid] = {'value': x, 'ref': f"supp.pdf/{sheet}/R{ri+1}C{ci+1}"}

records = []
for pid in range(81, 129):
    if pid in score and pid in truth:
        records.append({
            'id': f'P{pid}',
            'score': {'ref': score[pid]['ref'], 'threshold': 0.3487, 'op': '<='},
            'truth': {'ref': truth[pid]['ref'], 'map': {'cCR': 1, 'TRG 0': 1, 'TRG 1': 1, 'TRG 2': 0, 'TRG 3': 0, '0': 1, '1': 1, '2': 0, '3': 0}}
        })

if len(records) == 48:
    status = 'computed'
    blocked = ''
else:
    status = 'blocked'
    blocked = f"Could identify only {len(records)} of 48 validation rows with separate day-24 combined-chemoradiation ratios and clinical TRG/cCR outcomes."

CONTRACT = {
    'status': status,
    'fields': {
        'unit': {'value': 'patient', 'evidence': ['article:p28'], 'explanation': 'P81-P128 are 48 validation patients, each with one corresponding organoid line.'},
        'platform': {'value': 'organoid', 'evidence': ['article:p16'], 'explanation': 'Predictions are from patient-derived rectal cancer organoids.'},
        'readout': {'value': 'size_viability', 'evidence': ['article:p16','article:p29'], 'explanation': 'Day-24 to day-0 organoid size recovery ratio after combined chemoradiation.'},
        'direction': {'value': 'lower_sensitive', 'evidence': ['article:p16'], 'explanation': 'Ratios at or below 0.3487 are organoid-sensitive and predict good clinical response.'},
