        'patient_mapping': {'value': 'individual_available', 'evidence': ['article:p16','article:p28'], 'explanation': 'Each validation patient P81-P128 maps to a correspondingly numbered organoid O81-O128.'},
        'regimen_match': {'value': 'matched', 'evidence': ['article:p26','article:p28'], 'explanation': 'Organoid combined chemoradiation is compared with clinical neoadjuvant combined chemoradiation response.'},
        'n_units': {'value': 48, 'evidence': ['article:p28'], 'explanation': 'Independent validation cohort denominator.'},
        'split': {'value': 'independent_test', 'evidence': ['article:p16','article:p28'], 'explanation': 'P81-P128 form the held-out validation cohort; P1-P80 formed discovery.'}
    },
    'headline': {
        'metric': 'accuracy',
        'reported': 0.9375,
        'reported_evidence': ['article:p28','article:p5'],
        'threshold': 0.3487,
        'op': '<=',
        'score_direction': 'higher',
        'records': records,
        'blocked_reason': blocked
    },
    'notes': ['Truth is good for cCR, pTRG 0, or pTRG 1 and poor for pTRG 2 or 3.', '45 of 48 validation predictions agree; the reported exceptions are P104, P105, and P124.']
}
print('truth', len(truth), 'score', len(score), 'records', len(records))"}
